//! TLS is the transport protection.  A separate, fresh application key is used
//! for every control session so a packet from an earlier connection is useless.
use base64::{engine::general_purpose::URL_SAFE_NO_PAD, Engine};
use hmac::{Hmac, Mac};
use qrcodegen::{QrCode, QrCodeEcc};
use rand::RngCore;
use rcgen::{CertificateParams, DistinguishedName, DnType, KeyPair};
use rustls::{pki_types::{CertificateDer, PrivateKeyDer, PrivatePkcs8KeyDer}, ServerConfig, ServerConnection, StreamOwned};
use serde::{Deserialize, Serialize}; use sha2::{Digest,Sha256};
use std::{collections::{HashMap,HashSet},io::{BufRead,BufReader,Write},net::{IpAddr,Ipv4Addr,TcpListener,TcpStream},sync::{Arc,Mutex},thread,time::{Duration,Instant,SystemTime,UNIX_EPOCH}};
pub const COMPANION_PORT:u16=49876; const ENROLLMENT_TTL:Duration=Duration::from_secs(120); const SESSION_TTL:Duration=Duration::from_secs(15*60); const MAX_LINE:usize=16384; type HmacSha256=Hmac<Sha256>;
#[derive(Clone,Serialize)] pub struct PairRequest{pub request_id:String,pub name:String,pub device_id:String}
#[derive(Clone,Serialize)] pub struct TrustedDevice{pub device_id:String,pub name:String}
#[derive(Clone,Serialize)] pub struct CompanionSnapshot{pub running:bool,pub port:u16,pub pending:Vec<PairRequest>,pub trusted_devices:Vec<TrustedDevice>,pub active_sessions:usize,pub qr_payload:Option<String>,pub qr_svg:Option<String>,pub expires_at:Option<u64>}
struct Enrollment{token:[u8;32],expires:Instant,expires_at:u64,used:bool} struct Pending{request:PairRequest,secret:[u8;32],created:Instant} struct Device{name:String,secret:[u8;32]} struct Session{device_id:String,key:[u8;32],last_sequence:u64,expires:Instant} struct Identity{cert:CertificateDer<'static>,key:PrivateKeyDer<'static>,pin:String}
struct Inner{running:bool,enrollment:Option<Enrollment>,pending:HashMap<String,Pending>,trusted:HashMap<String,Device>,sessions:HashMap<String,Session>,used_open_nonces:HashSet<String>,endpoint:Option<Ipv4Addr>,identity:Identity} #[derive(Clone)] pub struct CompanionState(Arc<Mutex<Inner>>);
fn random<const N:usize>()->[u8;N]{let mut b=[0;N];rand::thread_rng().fill_bytes(&mut b);b} fn b64(v:impl AsRef<[u8]>)->String{URL_SAFE_NO_PAD.encode(v)} fn unix()->u64{SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default().as_secs()} fn private(ip:Ipv4Addr)->bool{ip.is_private()||ip.is_link_local()} fn private_peer(ip:IpAddr)->bool{matches!(ip,IpAddr::V4(v)if private(v))}
fn lan_ip()->Result<Ipv4Addr,String>{let s=std::net::UdpSocket::bind("0.0.0.0:0").map_err(|e|e.to_string())?;s.connect("192.0.2.1:9").map_err(|e|e.to_string())?;match s.local_addr().map_err(|e|e.to_string())?.ip(){IpAddr::V4(v)if private(v)=>Ok(v),_=>Err("Connect to private Wi-Fi or Ethernet before starting CoreLink Companion.".into())}}
fn identity()->Identity{let mut p=CertificateParams::new(vec!["CoreLink.local".into()]).expect("cert");let mut d=DistinguishedName::new();d.push(DnType::CommonName,"CoreLink local companion");p.distinguished_name=d;let k=KeyPair::generate().expect("key");let c=p.self_signed(&k).expect("cert");let der=c.der().clone();Identity{pin:b64(Sha256::digest(der.as_ref())),cert:der,key:PrivateKeyDer::Pkcs8(PrivatePkcs8KeyDer::from(k.serialize_der()))}}
fn config(i:&Identity)->Result<Arc<ServerConfig>,String>{ServerConfig::builder().with_no_client_auth().with_single_cert(vec![i.cert.clone()],i.key.clone_key()).map(Arc::new).map_err(|e|e.to_string())} fn send<S:Serialize,W:Write>(w:&mut W,v:&S)->std::io::Result<()> {let mut b=serde_json::to_vec(v)?;b.push(b'\n');w.write_all(&b)?;w.flush()} fn read<T:for<'a>Deserialize<'a>,R:BufRead>(r:&mut R)->Result<T,String>{let mut b=Vec::new();r.read_until(b'\n',&mut b).map_err(|_|"read failed")?;if b.is_empty()||b.len()>MAX_LINE{return Err("invalid message".into())};serde_json::from_slice(&b).map_err(|_|"invalid message".into())}
fn qr_svg(v:&str)->String{let q=QrCode::encode_text(v,QrCodeEcc::Medium).expect("qr");let z=3;let n=q.size()+z*2;let mut p=String::new();for y in 0..q.size(){for x in 0..q.size(){if q.get_module(x,y){p.push_str(&format!("M{} {}h1v1h-1z",x+z,y+z))}}}format!(r#"<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {n} {n}"><rect width="100%" height="100%" fill="white"/><path fill="black" d="{p}"/></svg>"#)}
fn transcript(parts:&[&str])->Vec<u8>{let mut s="corelink-v3".to_string();for p in parts{s.push('\n');s.push_str(p)}s.into_bytes()} fn check(k:&[u8;32],m:&[u8],tag:&str)->bool{let Ok(t)=URL_SAFE_NO_PAD.decode(tag)else{return false};let mut h=HmacSha256::new_from_slice(k).expect("hmac");h.update(m);h.verify_slice(&t).is_ok()} fn sign(k:&[u8;32],m:&[u8])->String{let mut h=HmacSha256::new_from_slice(k).expect("hmac");h.update(m);b64(h.finalize().into_bytes())} fn session_key(k:&[u8;32],sid:&str,cn:&str,sn:&str)->[u8;32]{let mut h=HmacSha256::new_from_slice(k).expect("hmac");h.update(&transcript(&["session-key",sid,cn,sn]));h.finalize().into_bytes().into()}
impl Default for CompanionState{fn default()->Self{Self(Arc::new(Mutex::new(Inner{running:false,enrollment:None,pending:HashMap::new(),trusted:HashMap::new(),sessions:HashMap::new(),used_open_nonces:HashSet::new(),endpoint:None,identity:identity()})))}}
impl CompanionState{pub fn start(&self)->Result<(),String>{let ip=lan_ip()?;let l=TcpListener::bind((ip,COMPANION_PORT)).map_err(|e|format!("Could not bind CoreLink to {ip}: {e}"))?;l.set_nonblocking(true).map_err(|e|e.to_string())?;{let mut i=self.0.lock().map_err(|_|"state lock")?;if i.running{return Ok(())}i.running=true;i.endpoint=Some(ip);i.enrollment=Some(Enrollment{token:random(),expires:Instant::now()+ENROLLMENT_TTL,expires_at:unix()+120,used:false});}let st=self.clone();thread::spawn(move||loop{match l.accept(){Ok((s,p))if private_peer(p.ip())=>{let x=st.clone();thread::spawn(move||serve(s,x));},Ok(_)=>{},Err(e)if e.kind()==std::io::ErrorKind::WouldBlock=>{if !st.running(){break}thread::sleep(Duration::from_millis(75))},Err(_)=>break}});Ok(())} pub fn stop(&self){if let Ok(mut i)=self.0.lock(){i.running=false;i.enrollment=None;i.pending.clear();i.sessions.clear();i.used_open_nonces.clear()}} fn running(&self)->bool{self.0.lock().map(|i|i.running).unwrap_or(false)}
pub fn snapshot(&self)->CompanionSnapshot{let mut i=self.0.lock().expect("state");i.sessions.retain(|_,s|s.expires>Instant::now());let(q,svg,e)=match(&i.enrollment,i.endpoint){(Some(x),Some(ip))if !x.used&&x.expires>Instant::now()=>{let q=format!("corelink://pair?v=3&host={ip}&port={COMPANION_PORT}&pin={}&token={}&expires={}",i.identity.pin,b64(x.token),x.expires_at);(Some(q.clone()),Some(qr_svg(&q)),Some(x.expires_at))},_=>(None,None,None)};CompanionSnapshot{running:i.running,port:COMPANION_PORT,pending:i.pending.values().map(|p|p.request.clone()).collect(),trusted_devices:i.trusted.iter().map(|(id,d)|TrustedDevice{device_id:id.clone(),name:d.name.clone()}).collect(),active_sessions:i.sessions.len(),qr_payload:q,qr_svg:svg,expires_at:e}} pub fn approve(&self,id:&str)->Result<(),String>{let mut i=self.0.lock().map_err(|_|"state lock")?;let Some(p)=i.pending.remove(id)else{return Err("Pairing request expired".into())};if p.created.elapsed()>ENROLLMENT_TTL{return Err("Pairing request expired".into())}i.trusted.insert(p.request.device_id,Device{name:p.request.name,secret:p.secret});Ok(())}pub fn reject(&self,id:&str)->Result<(),String>{self.0.lock().map_err(|_|"state lock")?.pending.remove(id).map(|_|()).ok_or("Pairing request expired".into())}pub fn revoke(&self,id:&str)->Result<(),String>{let mut i=self.0.lock().map_err(|_|"state lock")?;i.trusted.remove(id);i.sessions.retain(|_,s|s.device_id!=id);Ok(())}}
#[derive(Deserialize)]#[serde(tag="type",rename_all="snake_case")]enum Request{Enroll{token:String,device_id:String,name:String},SessionOpen{device_id:String,client_nonce:String,mac:String},Input{session_id:String,sequence:u64,payload:Input,mac:String},Disconnect{session_id:String,sequence:u64,mac:String}} #[derive(Clone,Deserialize,Serialize)]#[serde(tag="kind",rename_all="snake_case")]pub enum Input{Move{dx:i32,dy:i32},Button{button:String,down:bool},Click{button:String},Scroll{dy:i32},Key{key:String,ctrl:bool,alt:bool,shift:bool},Text{text:String}}
fn serve(socket:TcpStream,state:CompanionState){let c={let i=match state.0.lock(){Ok(v)=>v,Err(_)=>return};match config(&i.identity){Ok(v)=>v,Err(_)=>return}};let mut tls=StreamOwned::new(match ServerConnection::new(c){Ok(v)=>v,Err(_)=>return},socket);let _=tls.sock.set_read_timeout(Some(Duration::from_secs(10)));let req={let mut r=BufReader::new(&mut tls);read(&mut r)};match req{Ok(Request::Enroll{token,device_id,name})=>enroll(&mut tls,state,token,device_id,name),Ok(Request::SessionOpen{device_id,client_nonce,mac})=>open(&mut tls,state,device_id,client_nonce,mac),Ok(Request::Input{session_id,sequence,payload,mac})=>input(&mut tls,state,session_id,sequence,payload,mac),Ok(Request::Disconnect{session_id,sequence,mac})=>disconnect(&mut tls,state,session_id,sequence,mac),Err(_)=>{}}}
fn enroll<W:Write>(o:&mut W,s:CompanionState,t:String,id:String,name:String){if id.len()>96||name.len()>80{return}let Ok(t)=URL_SAFE_NO_PAD.decode(t)else{return};let rid=b64(random::<16>());let secret=random();let ok={let mut i=match s.0.lock(){Ok(v)=>v,Err(_)=>return};match i.enrollment.as_mut(){Some(e)if !e.used&&e.expires>Instant::now()&&t.as_slice()==e.token=>{e.used=true;i.pending.insert(rid.clone(),Pending{request:PairRequest{request_id:rid.clone(),name,device_id:id.clone()},secret,created:Instant::now()});true},_=>false}};if !ok{let _=send(o,&serde_json::json!({"type":"rejected"}));return}let _=send(o,&serde_json::json!({"type":"approval_required","request_id":rid}));for _ in 0..120{thread::sleep(Duration::from_millis(500));if s.0.lock().ok().and_then(|i|i.trusted.get(&id).map(|d|d.secret==secret)).unwrap_or(false){let _=send(o,&serde_json::json!({"type":"paired","secret":b64(secret),"session_ttl":SESSION_TTL.as_secs()}));return}}}
fn open<W:Write>(o:&mut W,s:CompanionState,did:String,cn:String,tag:String){if URL_SAFE_NO_PAD.decode(&cn).ok().filter(|v|v.len()==32).is_none(){let _=send(o,&serde_json::json!({"type":"session_rejected"}));return}let r={let mut i=match s.0.lock(){Ok(v)=>v,Err(_)=>return};if !i.running||i.used_open_nonces.contains(&cn){None}else{let Some(d)=i.trusted.get(&did)else{return};if !check(&d.secret,&transcript(&["session-open",&did,&cn]),&tag){None}else{let sid=b64(random::<24>());let sn=b64(random::<32>());let k=session_key(&d.secret,&sid,&cn,&sn);let proof=sign(&k,&transcript(&["session-opened",&did,&sid,&sn]));i.sessions.retain(|_,x|x.device_id!=did);i.used_open_nonces.insert(cn);i.sessions.insert(sid.clone(),Session{device_id:did.clone(),key:k,last_sequence:0,expires:Instant::now()+SESSION_TTL});Some((sid,sn,proof))}}};match r{Some((id,sn,m))=>{let _=send(o,&serde_json::json!({"type":"session_opened","session_id":id,"server_nonce":sn,"expires_in":SESSION_TTL.as_secs(),"mac":m}));},None=>{let _=send(o,&serde_json::json!({"type":"session_rejected"}));}}}
fn input<W:Write>(o:&mut W,s:CompanionState,id:String,seq:u64,p:Input,tag:String){let b=match serde_json::to_string(&p){Ok(v)=>v,Err(_)=>return};let ok={let mut i=match s.0.lock(){Ok(v)=>v,Err(_)=>return};let now=Instant::now();let Some(x)=i.sessions.get_mut(&id)else{return};if x.expires<=now||seq<=x.last_sequence||!check(&x.key,&transcript(&["input",&id,&seq.to_string(),&b]),&tag){false}else if dispatch(p).is_ok(){x.last_sequence=seq;x.expires=now+SESSION_TTL;true}else{false}};let _=send(o,&serde_json::json!({"type":"ack","ok":ok}));}
fn disconnect<W:Write>(o:&mut W,s:CompanionState,id:String,seq:u64,tag:String){let ok={let mut i=match s.0.lock(){Ok(v)=>v,Err(_)=>return};let Some(x)=i.sessions.get(&id)else{return};let valid=x.expires>Instant::now()&&seq>x.last_sequence&&check(&x.key,&transcript(&["disconnect",&id,&seq.to_string()]),&tag);if valid{let _=i.sessions.remove(&id);}valid};let _=send(o,&serde_json::json!({"type":"disconnected","ok":ok}));}
fn dispatch(i:Input)->Result<(),String>{match &i{Input::Move{dx,dy}if dx.abs()>5000||dy.abs()>5000=>Err("movement out of range".into()),Input::Scroll{dy}if dy.abs()>5000=>Err("scroll out of range".into()),Input::Button{button,..}|Input::Click{button}if button!="left"&&button!="right"=>Err("button not allowed".into()),Input::Key{key,..}if key.len()>32=>Err("key not allowed".into()),Input::Text{text}if text.len()>2048=>Err("text too long".into()),_=>send_input(i)}}
#[cfg(windows)]fn send_input(i:Input)->Result<(),String>{use windows::Win32::UI::Input::KeyboardAndMouse::{keybd_event,mouse_event,KEYEVENTF_KEYUP,MOUSEEVENTF_LEFTDOWN,MOUSEEVENTF_LEFTUP,MOUSEEVENTF_MOVE,MOUSEEVENTF_RIGHTDOWN,MOUSEEVENTF_RIGHTUP,MOUSEEVENTF_WHEEL,VK_CONTROL,VK_MENU,VK_SHIFT};unsafe{match i{Input::Move{dx,dy}=>mouse_event(MOUSEEVENTF_MOVE,dx,dy,0,0),Input::Scroll{dy}=>mouse_event(MOUSEEVENTF_WHEEL,0,0,dy,0),Input::Button{button,down}=>{let f=match(button.as_str(),down){("left",true)=>MOUSEEVENTF_LEFTDOWN,("left",false)=>MOUSEEVENTF_LEFTUP,("right",true)=>MOUSEEVENTF_RIGHTDOWN,("right",false)=>MOUSEEVENTF_RIGHTUP,_=>return Err("button not allowed".into())};mouse_event(f,0,0,0,0)},Input::Click{button}=>{let(d,u)=if button=="left"{(MOUSEEVENTF_LEFTDOWN,MOUSEEVENTF_LEFTUP)}else{(MOUSEEVENTF_RIGHTDOWN,MOUSEEVENTF_RIGHTUP)};mouse_event(d,0,0,0,0);mouse_event(u,0,0,0,0)},Input::Key{key,ctrl,alt,shift}=>{if ctrl{keybd_event(VK_CONTROL.0 as u8,0,Default::default(),0)}if alt{keybd_event(VK_MENU.0 as u8,0,Default::default(),0)}if shift{keybd_event(VK_SHIFT.0 as u8,0,Default::default(),0)}for c in key.bytes(){keybd_event(c.to_ascii_uppercase(),0,Default::default(),0);keybd_event(c.to_ascii_uppercase(),0,KEYEVENTF_KEYUP,0)}if shift{keybd_event(VK_SHIFT.0 as u8,0,KEYEVENTF_KEYUP,0)}if alt{keybd_event(VK_MENU.0 as u8,0,KEYEVENTF_KEYUP,0)}if ctrl{keybd_event(VK_CONTROL.0 as u8,0,KEYEVENTF_KEYUP,0)}},Input::Text{text}=>for c in text.bytes(){keybd_event(c,0,Default::default(),0);keybd_event(c,0,KEYEVENTF_KEYUP,0)}}};Ok(())} #[cfg(not(windows))]fn send_input(_:Input)->Result<(),String>{Ok(())}
#[cfg(test)]mod tests{use super::*;
#[test]fn pairing_approval_creates_a_trusted_credential(){let state=CompanionState::default();let request=PairRequest{request_id:"pair".into(),name:"Samsung".into(),device_id:"phone".into()};state.0.lock().unwrap().pending.insert("pair".into(),Pending{request,secret:[9;32],created:Instant::now()});state.approve("pair").unwrap();assert_eq!(state.0.lock().unwrap().trusted.get("phone").unwrap().secret,[9;32]);}
#[test]fn reconnect_keys_are_independent(){let d=[7;32];assert_ne!(session_key(&d,"one","a","b"),session_key(&d,"two","c","d"))}
#[test]fn replay_from_terminated_session_fails(){let d=[7;32];let a=session_key(&d,"old","a","b");let b=session_key(&d,"new","c","d");let t=sign(&a,&transcript(&["input","old","1","{}"]));assert!(!check(&b,&transcript(&["input","new","1","{}"]),&t))}
#[test]fn invalid_credentials_cannot_open_or_control(){let good=[1;32];let bad=[2;32];let open=sign(&good,&transcript(&["session-open","phone","nonce"]));assert!(!check(&bad,&transcript(&["session-open","phone","nonce"]),&open));}
#[test]fn revocation_removes_every_active_session(){let state=CompanionState::default();{let mut i=state.0.lock().unwrap();i.trusted.insert("phone".into(),Device{name:"Samsung".into(),secret:[3;32]});i.sessions.insert("one".into(),Session{device_id:"phone".into(),key:[4;32],last_sequence:0,expires:Instant::now()+SESSION_TTL});}state.revoke("phone").unwrap();let i=state.0.lock().unwrap();assert!(!i.trusted.contains_key("phone"));assert!(i.sessions.is_empty());}
#[test]fn expired_sessions_are_not_active(){let state=CompanionState::default();state.0.lock().unwrap().sessions.insert("old".into(),Session{device_id:"phone".into(),key:[4;32],last_sequence:0,expires:Instant::now()-Duration::from_secs(1)});assert_eq!(state.snapshot().active_sessions,0);}
#[test]fn disconnect_is_authenticated(){let k=[1;32];let t=sign(&k,&transcript(&["disconnect","s","2"]));assert!(check(&k,&transcript(&["disconnect","s","2"]),&t));assert!(!check(&k,&transcript(&["disconnect","s","3"]),&t))}
#[test]fn input_bounds_hold(){assert!(dispatch(Input::Move{dx:5001,dy:0}).is_err())}}
